const app=document.querySelector('#app'); let state=await loadState();
const euro=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(Number(n)||0);
const parseAmount=value=>{let s=String(value??'').trim().replace(/\s|€/g,'');if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');return Number(s)};
const realBalance=()=>getRealBalance(state);
function shell(body){const todoScreen=body.includes('todo-head');document.documentElement.dataset.appColor=state.appColor||'Blu';document.documentElement.dataset.todoColor=state.todo?.color||'Verde E.D.S.';const logo=todoScreen?'../assets/eds-green-approved.png':(state.appColor==='Verde'?'../assets/eds-green-approved.png':'../assets/eds-blue-approved.png');body=body.replaceAll('<span class="eds">E.D.S.</span>','<img class="eds-logo" src="'+logo+'" alt="E.D.S.">');app.innerHTML='<main class="app-shell"><section class="screen"><div class="screen-inner">'+body+'</div></section></main>'}
function landing(){shell('<section class="brand card"><div class="brand-top"><img class="brand-logo" src="../assets/eds-blue-approved.png" alt="E.D.S."><span class="eyebrow">IL TUO SPAZIO PERSONALE</span></div><div class="brand-copy"><strong>In Ordine</strong><p>Conti e cose da fare, in un unico posto.</p></div><img class="hero-art home-art" src="../assets/inordine-home-couple.webp" alt="Una donna e un uomo sorridenti organizzano insieme la loro giornata"><div class="brand-ribbon">Più tempo per ciò che conta <span aria-hidden="true">♥</span></div></section><h2 class="home-section-title">Da dove vuoi iniziare?</h2><div class="home-paired-grid"><div class="home-pair"><button class="area-card money home-area" data-go="money"><img class="home-tile-art" src="../assets/conti-wallet-balance.webp" alt="Portafoglio blu e moneta"><b>Conti economici</b><small>Saldo, entrate, pagamenti e movimenti</small><span class="tile-arrow" aria-hidden="true">↗</span></button><button class="home-pair-notice finance-notice" data-go="finance-notifications"><svg class="bell-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Notifiche Conti economici</button></div><div class="home-pair"><button class="area-card todo home-area" data-go="todo"><img class="home-tile-art" src="../assets/todo-couple-checklist.webp" alt="Lista delle attività"><b>Cose da fare</b><small>Attività, scadenze e promemoria</small><span class="tile-arrow" aria-hidden="true">↗</span></button><button class="home-pair-notice todo-notice" data-go="todo-notifications"><svg class="bell-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Notifiche Cose da fare</button></div></div><p class="home-note">Un piccolo passo alla volta, tutto al suo posto.</p>')}
function monthName(ym){const [y,m]=ym.split('-').map(Number);return new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(new Date(y,m-1,1))}
function projectedBalance(){return calculateProjectedBalance(state)}
function monthEndBalance(ym=monthKey()){return calculateMonthEndBalance(state,ym)}
function money(){shell('<header class="page-header money-head"><button data-go="landing" aria-label="Torna alla home">‹</button><div><small>IL TUO DENARO</small><h1>Conti economici</h1></div><img class="eds-logo" src="../assets/eds-blue-approved.png" alt="E.D.S."></header><div class="finance-actions"><button class="finance-tile income" data-go="income"><span class="finance-art-frame"><img class="section-art finance-art" src="../assets/conti-income-couple.webp" alt="Una coppia festeggia le entrate accanto a monete e una freccia verde"></span><span class="finance-tile-copy"><b>Entrate</b><small>Vedi tutte</small></span><span class="finance-arrow" aria-hidden="true">›</span></button><button class="finance-tile expense" data-go="expense"><span class="finance-art-frame"><img class="section-art finance-art" src="../assets/conti-payment-couple.webp" alt="Una coppia controlla un pagamento con portafoglio blu"></span><span class="finance-tile-copy"><b>Pagamenti</b><small>Vedi tutti</small></span><span class="finance-arrow" aria-hidden="true">›</span></button></div><h2 class="section-kicker">Riepilogo conti</h2><section class="balance card"><div class="balance-art-wrap"><div><div class="balance-label"><span class="balance-icon">€</span><small>Saldo reale</small></div><strong>'+euro(realBalance())+'</strong></div><img class="balance-art" src="../assets/conti-wallet-balance.webp" alt="Portafoglio blu tridimensionale e moneta euro"></div><small class="forecast-label">Saldo previsto complessivo <b>'+euro(projectedBalance())+'</b></small><button class="balance-update-button" id="setBalance">Aggiorna saldo reale</button></section><section class="finance-metrics-separated card"><div class="finance-summary-metrics"><span>Da ricevere <b>'+euro(financeTotals(state,'income').pending)+'</b></span><span>Da pagare <b>'+euro(financeTotals(state,'expense').pending)+'</b></span><span>Saldo a fine mese <b>'+euro(monthEndBalance())+'</b></span></div></section><div class="quick-links"><button class="wide card" data-go="movements"><span class="link-icon">⇄</span><span>Movimenti<small>Entrate e pagamenti registrati</small></span><b aria-hidden="true">›</b></button><button class="wide card" data-go="settings"><span class="link-icon">⚙</span><span>Impostazioni<small>Personalizza l’app</small></span><b aria-hidden="true">›</b></button></div>')}
const uid=()=>crypto.randomUUID();
const nativePlugin=name=>Capacitor.isNativePlatform()?({LocalNotifications,Filesystem,Share,NativeBiometric})[name]||null:null;
async function syncTodoNotifications(){await syncNotifications(state,nativePlugin('LocalNotifications'))}
function ensureNeverOccurrences(){let changed=false;for(const [lists,target] of [[[state.entries,state.history],state.entries],[[state.todo.tasks,state.todo.done],state.todo.tasks]]){const groups=new Map();for(const item of lists.flat())if(item.seriesId&&item.recurrenceRule?.end==='never'){if(!groups.has(item.seriesId))groups.set(item.seriesId,[]);groups.get(item.seriesId).push(item)}for(const [seriesId,items] of groups){const root=items.find(x=>x.id===seriesId)||items[0];if(!root.date)continue;const precision=root.datePrecision||'day',known=new Set(items.map(x=>x.occurrenceIndex));for(const occurrence of generateOccurrenceDates(root.date,precision,root.recurrenceRule,{horizonMonths:18})){if(!occurrence.index||known.has(occurrence.index))continue;target.push({...root,id:uid(),date:occurrence.date,seriesId,occurrenceIndex:occurrence.index,recurrenceSource:seriesId,completedAt:undefined});changed=true}}}return changed}
const monthOf=x=>(x.date||'').slice(0,7);
function addMonths(ym,n){const [y,m]=ym.split('-').map(Number),d=new Date(y,m-1+n,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
let flowMonths={income:monthKey(),expense:monthKey()};
function deleteMoney(id){const i=state.entries.findIndex(x=>x.id===id);if(i>=0)state.entries.splice(i,1)}
function dateControls(prefix,item={}){
 const precision=item.datePrecision||(item.date?.length===7?'month':item.date?'day':'none');
 return `<label>Quando<select id="${prefix}DateMode"><option value="day" ${precision==='day'?'selected':''}>Data precisa</option><option value="month" ${precision==='month'?'selected':''}>Solo mese e anno</option><option value="none" ${precision==='none'?'selected':''}>Senza data</option></select></label><label data-date-day="${prefix}" ${precision==='day'?'':'hidden'}>Data precisa<input id="${prefix}Date" type="date" value="${precision==='day'?escapeHtml(item.date||''):''}"></label><label data-date-month="${prefix}" ${precision==='month'?'':'hidden'}>Mese e anno<input id="${prefix}Month" type="month" value="${precision==='month'?escapeHtml(item.date||''):''}"></label>`;
}
function recurrenceFields(prefix,item={}){
 const r=normalizeRecurrenceRule(item.recurrenceRule||item.recurrence,25),unit=r?.unit||'month',interval=r?.interval||1,end=r?.end||'count',count=r?.count||(unit==='year'?3:prefix.startsWith('todo')?25:12),legacy={day:'daily',week:'weekly',month:'monthly',year:'yearly'}[unit];
 return `<label>Ricorrenza<select id="${prefix}Recurrence"><option value="none" ${!r?'selected':''}>Non ripetere</option><option value="daily" ${r&&legacy==='daily'?'selected':''}>Ogni giorno</option><option value="weekly" ${r&&legacy==='weekly'?'selected':''}>Ogni settimana</option><option value="monthly" ${r&&legacy==='monthly'?'selected':''}>Ogni mese</option><option value="yearly" ${r&&legacy==='yearly'?'selected':''}>Ogni anno</option><option value="custom" ${r&&interval>1?'selected':''}>Intervallo personalizzato</option></select></label><div class="recurrence-options" data-recurrence-options="${prefix}" ${r&&interval>1?'':'hidden'}><label>Ogni <input id="${prefix}RecurrenceInterval" type="number" min="1" max="365" value="${interval}"></label><label>Unità<select id="${prefix}RecurrenceUnit"><option value="day" ${unit==='day'?'selected':''}>giorno/i</option><option value="week" ${unit==='week'?'selected':''}>settimana/e</option><option value="month" ${unit==='month'?'selected':''}>mese/i</option><option value="year" ${unit==='year'?'selected':''}>anno/i</option></select></label><label>Termina<select id="${prefix}RecurrenceEnd"><option value="count" ${end==='count'?'selected':''}>Dopo un numero di occorrenze</option><option value="date" ${end==='date'?'selected':''}>A una data</option><option value="never" ${end==='never'?'selected':''}>Mai</option></select></label><label data-rec-count="${prefix}" ${end==='count'?'':'hidden'}>Occorrenze totali<input id="${prefix}RecurrenceCount" type="number" min="1" max="5000" value="${count}"></label><label data-rec-until="${prefix}" ${end==='date'?'':'hidden'}>Fino al<input id="${prefix}RecurrenceUntil" type="date" value="${escapeHtml(r?.until||'')}"></label></div>`;
}
function reminderControls(prefix,item={},domain='todo'){
 const r=item.reminder||{},enabled=r.enabled??(domain==='todo'?Boolean(item.notify):false),mode=r.mode||'due',time=r.time||'',advance=r.advanceMinutes??(domain==='todo'?state.todo.notifications?.rule?.advanceMinutes||0:0),custom=r.customAt||'';
 return `<label class="check"><input id="${prefix}Notify" type="checkbox" ${enabled?'checked':''}> Attiva notifica</label><div data-reminder-options="${prefix}" ${enabled?'':'hidden'}><label>Promemoria<select id="${prefix}ReminderMode"><option value="due" ${mode==='due'?'selected':''}>In base alla scadenza</option><option value="custom" ${mode==='custom'?'selected':''}>Data e ora personalizzate</option></select></label><label>Orario<input id="${prefix}ReminderTime" type="time" value="${escapeHtml(time)}"></label><label>Anticipo (minuti)<input id="${prefix}Advance" type="number" min="0" max="525600" value="${advance}"></label><label data-reminder-custom="${prefix}" ${mode==='custom'?'':'hidden'}>Data e ora promemoria<input id="${prefix}CustomAt" type="datetime-local" value="${escapeHtml(custom)}"></label></div>`;
}
function syncDateMode(prefix){const m=document.querySelector(`#${prefix}DateMode`)?.value||'day',d=document.querySelector(`[data-date-day="${prefix}"]`),mo=document.querySelector(`[data-date-month="${prefix}"]`);if(d)d.hidden=m!=='day';if(mo)mo.hidden=m!=='month';syncRecurrenceMode(prefix)}
function syncRecurrenceMode(prefix){const selector=document.querySelector(`#${prefix}Recurrence`),dateMode=document.querySelector(`#${prefix}DateMode`)?.value;if(dateMode==='none'&&selector&&selector.value!=='none')selector.value='none';if(dateMode==='month'&&selector&&['daily','weekly'].includes(selector.value)){selector.value='monthly';const unitSelect=document.querySelector(`#${prefix}RecurrenceUnit`);if(unitSelect)unitSelect.value='month'}const unit=selector?.value||'none',options=document.querySelector(`[data-recurrence-options="${prefix}"]`),end=document.querySelector(`#${prefix}RecurrenceEnd`)?.value||'count';if(options)options.hidden=unit!=='custom';const c=document.querySelector(`[data-rec-count="${prefix}"]`),u=document.querySelector(`[data-rec-until="${prefix}"]`);if(c)c.hidden=end!=='count';if(u)u.hidden=end!=='date'}
function syncReminderMode(prefix){const on=document.querySelector(`#${prefix}Notify`)?.checked,opts=document.querySelector(`[data-reminder-options="${prefix}"]`),custom=document.querySelector(`[data-reminder-custom="${prefix}"]`);if(opts)opts.hidden=!on;if(custom)custom.hidden=!on||document.querySelector(`#${prefix}ReminderMode`)?.value!=='custom'}
function recurrenceFormValue(prefix){const unitSelect=document.querySelector(`#${prefix}Recurrence`),value=unitSelect?.value||'none';if(value==='none')return null;const unit=value==='custom'?document.querySelector(`#${prefix}RecurrenceUnit`)?.value:({daily:'day',weekly:'week',monthly:'month',yearly:'year'}[value]||'month');const defaultCount=unit==='year'?3:prefix.startsWith('todo')?25:12;return normalizeRecurrenceRule({unit,interval:value==='custom'?document.querySelector(`#${prefix}RecurrenceInterval`)?.value:1,end:document.querySelector(`#${prefix}RecurrenceEnd`)?.value||'count',count:document.querySelector(`#${prefix}RecurrenceCount`)?.value||defaultCount,until:document.querySelector(`#${prefix}RecurrenceUntil`)?.value||''},defaultCount)}
function reminderFormValue(prefix){const enabled=Boolean(document.querySelector(`#${prefix}Notify`)?.checked),mode=document.querySelector(`#${prefix}ReminderMode`)?.value||'due';return {enabled,mode,time:document.querySelector(`#${prefix}ReminderTime`)?.value||'',advanceMinutes:Number(document.querySelector(`#${prefix}Advance`)?.value||0),customAt:document.querySelector(`#${prefix}CustomAt`)?.value||''}}
function addOccurrences(collection,base,rule,precision){if(!rule)return;const dates=generateOccurrenceDates(base.date,precision,rule,{horizonMonths:18});for(const occurrence of dates){if(occurrence.index===0)continue;collection.push({...base,id:uid(),date:occurrence.date,seriesId:base.seriesId,occurrenceIndex:occurrence.index,recurrenceSource:base.seriesId});}}
function itemInSeries(item){return item.seriesId||item.recurrenceSource||item.id}
function removeMoneyItem(item){deleteMoneyRecord(state,item.id)}
function saveReminder(item,prefix){item.reminder=reminderFormValue(prefix);item.notify=item.reminder.enabled}
function dateAndRuleFromForm(prefix){const when=dateValueFromForm(prefix);let rule=recurrenceFormValue(prefix);if(when.datePrecision==='none')rule=null;if(when.datePrecision==='month'&&rule&&['day','week'].includes(rule.unit))rule={...rule,unit:'month'};return {...when,recurrenceRule:rule,recurrence:rule?({day:'daily',week:'weekly',month:'monthly',year:'yearly'}[rule.unit]||'none'):'none'};}

function editMoney(id){const x=state.history.find(e=>e.id===id)||state.entries.find(e=>e.id===id);if(!x)return;const isIncome=x.kind==='income',done=state.history.some(e=>e.id===id),cats=state.preferences.categories||defaultCategories,recurring=Boolean(x.seriesId||x.recurrenceSource||x.recurrenceRule);shell(`<header class="page-header money-head"><button data-go="${x.kind}">‹</button><div><small>CONTI ECONOMICI</small><h1>Modifica ${isIncome?'entrata':'pagamento'}</h1></div><span class="eds">E.D.S.</span></header><form id="moneyEditForm" data-id="${x.id}" data-done="${done}" data-series="${recurring}" class="card form-card"><label>Descrizione<input id="moneyEditDescription" value="${escapeHtml(x.description)}" required></label><label>Importo<input id="moneyEditAmount" inputmode="decimal" value="${x.amount}" required></label>${dateControls('moneyEdit',x)}${recurrenceFields('moneyEdit',x)}${reminderControls('moneyEdit',x,'finance')}<label>Categoria<select id="moneyEditCategory"><option value="">Scegli categoria</option>${cats.map(v=>`<option ${v===x.category?'selected':''}>${escapeHtml(v)}</option>`).join('')}</select></label><label>Fornitore / provenienza<input id="moneyEditSupplier" value="${escapeHtml(x.supplier||'')}"></label><button type="submit">Salva modifiche</button><button type="button" class="danger" data-delete-money="${x.id}">Elimina ${done?'movimento':'voce'}</button></form>`);syncDateMode('moneyEdit');syncRecurrenceMode('moneyEdit');syncReminderMode('moneyEdit')}
function fmtItalianDate(value){if(!value)return 'Senza data';if(value.length===4)return value;if(value.length===7){const [y,m]=value.split('-');return new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(new Date(Number(y),Number(m)-1,1))}const [y,m,d]=value.split('-');return d&&m&&y?new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'long',year:'numeric'}).format(new Date(Number(y),Number(m)-1,Number(d))):value}
function fmtDate(value){return fmtItalianDate(value)}
function flow(kind){
  const isIncome=kind==='income',title=isIncome?'Entrate':'Pagamenti',ym=flowMonths[kind]||monthKey(),filter=statusFilter(kind);
  let items=financePendingEntries(state).filter(x=>x.kind===kind&&(!x.date||monthOf(x)===ym));
  const completed=financeCompletedEntries(state).filter(x=>x.kind===kind&&(!x.date||monthOf(x)===ym));
  if(filter==='done')items=completed.map(x=>({...x,_done:true}));
  else if(filter==='all')items=[...items,...completed.map(x=>({...x,_done:true}))];
  items=items.filter(x=>matchesSearch(x,moneySearch[kind])).sort((a,b)=>(a.date||'9999-99-99').localeCompare(b.date||'9999-99-99'));
  const totals=moneyTotals(kind,ym);
  const rows=items.length?items.map(x=>'<article class="card task money-row" data-edit-money="'+x.id+'" data-done="'+Boolean(x._done)+'"><div><b>'+escapeHtml(x.description)+'</b><small>'+escapeHtml(x.category||'Altro')+' · '+fmtDate(x.date)+(x._done?' · '+(isIncome?'Ricevuta':'Pagato'):' · '+(isIncome?'Da ricevere':'Da pagare'))+'</small></div><div class="money-actions"><strong>'+euro(x.amount)+'</strong>'+(x._done?'<button data-undo-money="'+x.id+'">Annulla</button><button class="danger mini-danger" data-delete-money="'+x.id+'">Elimina</button>':'<button data-money-done="'+x.id+'">'+(isIncome?'Segna ricevuta':'Segna pagato')+'</button>')+'</div></article>').join(''):'<div class="card empty"><b>Nessuna voce</b><p>Nessun elemento per questo filtro.</p></div>';
  const tabs='<div class="filter-row"><button data-money-filter="'+kind+':all" class="'+(filter==='all'?'active':'')+'">Tutte</button><button data-money-filter="'+kind+':pending" class="'+(filter==='pending'?'active':'')+'">'+(isIncome?'Da ricevere':'Da pagare')+'</button><button data-money-filter="'+kind+':done" class="'+(filter==='done'?'active':'')+'">'+(isIncome?'Ricevute':'Pagati')+'</button><label class="compact-search"><span aria-hidden="true">⌕</span><input aria-label="Cerca entrate o pagamenti" data-money-search="'+kind+'" type="search" placeholder="Cerca" value="'+escapeHtml(moneySearch[kind])+'"></label></div>';
  shell('<header class="page-header money-head"><button data-go="money">‹</button><div><small>CONTI ECONOMICI</small><h1>'+title+'</h1></div><span class="eds">E.D.S.</span></header><div class="month-nav card"><button data-month-prev="'+kind+'">‹</button><b>'+monthName(ym)+'</b><button data-month-next="'+kind+'">›</button></div>'+tabs+rows+'<section class="card flow-totals"><div><span>'+(isIncome?'Da ricevere':'Da pagare')+'</span><b>'+euro(totals.pending)+'</b></div><div><span>'+(isIncome?'Ricevute':'Pagati')+'</span><b>'+euro(totals.done)+'</b></div><div class="grand"><span>Totale mese</span><strong>'+euro(totals.total)+'</strong></div></section><button class="wide card add-action" data-add-money="'+kind+'"><span class="action-plus" aria-hidden="true">+</span><span>Aggiungi '+(isIncome?'entrata':'pagamento')+'</span><b aria-hidden="true">›</b></button>');
}
function statusFilter(kind){return (state.preferences.moneyFilters||{})[kind]||'all'}
function moneyForm(kind){const isIncome=kind==='income',cats=state.preferences.categories||defaultCategories;shell(`<header class="page-header money-head"><button data-go="${kind}">‹</button><div><small>CONTI ECONOMICI</small><h1>Nuova ${isIncome?'entrata':'spesa'}</h1></div><img class="eds-logo" src="../assets/eds-blue-approved.png" alt="E.D.S."></header><form id="moneyForm" data-kind="${kind}" class="card form-card"><label>Descrizione<input id="moneyDescription" required autocomplete="off"></label><label>Importo<input id="moneyAmount" inputmode="decimal" required></label>${dateControls('money',{datePrecision:'day'})}${recurrenceFields('money')}<div class="optional-money-fields"><label>Categoria<select id="moneyCategory"><option value="">Scegli categoria</option>${cats.map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select></label><label>Fornitore / provenienza<input id="moneySupplier" autocomplete="off"></label></div>${reminderControls('money',{},'finance')}<button type="submit">Salva</button></form>`);syncDateMode('money');syncRecurrenceMode('money');syncReminderMode('money')}

let movementFilter='all',movementMonth=monthKey(),movementSearch='',moneySearch={income:'',expense:''},todoSearch={active:'',done:''};
const matchesSearch=(item,query)=>!query||[item.description,item.category,item.supplier,item.vendor].some(v=>String(v||'').toLocaleLowerCase('it').includes(query.toLocaleLowerCase('it')));

function movements(){const filtered=state.history.filter(x=>(movementFilter==='all'||x.kind===movementFilter)&&(!x.date||monthOf(x)===movementMonth));const rows=[...filtered].filter(x=>matchesSearch(x,movementSearch)).sort((a,b)=>(b.completedAt||'').localeCompare(a.completedAt||'')).map(x=>'<article class="card task money-row" data-edit-money="'+x.id+'" data-done="true"><div><b>'+escapeHtml(x.description)+'</b><small>'+fmtDate(x.date)+' · '+escapeHtml(x.category||'Altro')+'</small></div><strong class="'+(x.kind==='income'?'plus':'minus')+'">'+(x.kind==='income'?'+':'−')+euro(x.amount)+'</strong><div class="money-actions"><button data-undo-money="'+x.id+'">Annulla</button><button class="danger mini-danger" data-delete-money="'+x.id+'">Elimina</button></div></article>').join('');shell('<header class="page-header money-head"><button data-go="money">‹</button><div><small>CONTI ECONOMICI</small><h1>Movimenti</h1></div><span class="eds">E.D.S.</span></header><div class="month-nav card"><button data-movement-month="-1">‹</button><b>'+monthName(movementMonth)+'</b><button data-movement-month="1">›</button></div><div class="filter-row"><button data-movement-filter="all" class="'+(movementFilter==='all'?'active':'')+'">Tutti</button><button data-movement-filter="income" class="'+(movementFilter==='income'?'active':'')+'">Entrate</button><button data-movement-filter="expense" class="'+(movementFilter==='expense'?'active':'')+'">Pagamenti</button></div>'+'<label class="search-field">Cerca movimenti<input id="movementSearch" type="search" placeholder="Descrizione, categoria, fornitore" value="'+escapeHtml(movementSearch)+'"></label>'+(rows||'<div class="card empty"><b>Nessun movimento</b><p>Qui compariranno soltanto entrate ricevute e pagamenti realmente effettuati.</p></div>'))}
function monthKey(d=new Date()){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
function budgetCategory(){const ym=monthKey(),plans=state.budgetPlans||(state.budgetPlans=[]),i=plans.findIndex(x=>x.month===ym),plan=i>=0?plans[i]:{month:ym,total:0,limits:{}};const cats=state.preferences.categories||['Casa','Spesa','Auto','Salute','Tempo libero','Altro'];const rows=cats.map(cat=>{const spent=state.history.filter(x=>x.kind==='expense'&&monthOf(x)===ym&&x.category===cat).reduce((s,x)=>s+Number(x.amount||0),0),limit=Number(plan.limits?.[cat]||0);return '<article class="card budget-row"><div><b>'+escapeHtml(cat)+'</b><small>Speso '+euro(spent)+'</small></div><label>Limite<input inputmode="decimal" data-budget-category="'+escapeHtml(cat)+'" value="'+(limit||'')+'" placeholder="0"></label></article>'}).join('');shell('<header class="page-header money-head"><button data-go="budget">‹</button><div><small>BUDGET</small><h1>Limiti per categoria</h1></div><span class="eds">E.D.S.</span></header><form id="budgetCategoryForm">'+rows+'<button class="wide card" type="submit">Salva limiti</button></form>')}
function budget(){const ym=monthKey(),plan=(state.budgetPlans||[]).find(x=>x.month===ym)||{month:ym,total:0,limits:{}};const spent=state.history.filter(x=>x.kind==='expense'&&monthOf(x)===ym).reduce((s,x)=>s+Number(x.amount||0),0);shell('<header class="page-header money-head"><button data-go="summary">‹</button><div><small>CONTI ECONOMICI</small><h1>Budget</h1></div><span class="eds">E.D.S.</span></header><section class="balance card"><small>Budget mensile</small><strong>'+euro(plan.total)+'</strong><p>Speso: '+euro(spent)+' · Disponibile: '+euro(Math.max(0,Number(plan.total)-spent))+'</p><button id="editBudget">Imposta budget</button><button data-go="budget-categories">Limiti per categoria</button></section>')}
function todoSettings(){const n=state.todo.notifications||{};const list=state.todo.tasks.map(x=>`<label class="notification-entry"><input type="checkbox" data-notify-todo="${x.id}" ${x.reminder?.enabled||x.notify?'checked':''}><span><b>${escapeHtml(x.description)}</b><small>${fmtItalianDate(x.date)}</small></span><button type="button" data-edit-todo-notice="${x.id}">Quando</button></label>`).join('');shell(`<header class="page-header todo-head"><button data-go="todo">‹</button><div><small>COSE DA FARE</small><h1><svg class="bell-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Notifiche</h1></div><span class="eds">E.D.S.</span></header><form id="todoSettingsForm" class="card form-card"><label class="check"><input id="todoNotifications" type="checkbox" ${n.enabled?'checked':''}> Attiva tutte le notifiche</label><label>Ora predefinita<input id="todoNotifyTime" type="time" value="${escapeHtml(n.rule?.time||'09:00')}"></label><label>Anticipo predefinito (minuti)<input id="todoAdvance" type="number" min="0" value="${Number(n.rule?.advanceMinutes||0)}"></label><label class="check"><input id="todoDailySummary" type="checkbox" ${n.dailySummary?'checked':''}> Riepilogo giornaliero</label><label>Ora del riepilogo<input id="todoDailySummaryTime" type="time" value="${escapeHtml(n.dailySummaryTime||'18:00')}"></label><button type="submit">Salva impostazioni generali</button></form><section class="card notification-list"><h2>Notifiche per ogni attività</h2>${list||'<p>Nessuna attività inserita.</p>'}</section><button class="wide card settings-action" data-go="todo-settings-color">Colori attività</button>`)}
function todoColorSettings(){shell(`<header class="page-header todo-head"><button data-go="todo-notifications">‹</button><div><small>COSE DA FARE</small><h1>Colori</h1></div><span class="eds">E.D.S.</span></header><form id="todoColorForm" class="card form-card"><label>Colore<select id="todoColor"><option ${state.todo.color==='Verde E.D.S.'?'selected':''}>Verde E.D.S.</option><option ${state.todo.color==='Blu'?'selected':''}>Blu</option><option ${state.todo.color==='Viola'?'selected':''}>Viola</option><option ${state.todo.color==='Arancio'?'selected':''}>Arancio</option></select></label><button type="submit">Salva</button></form>`)}
async function exportBackup(){const payload=JSON.stringify({format:'in-ordine-v2',exportedAt:new Date().toISOString(),state},null,2);const fs=nativePlugin('Filesystem'),share=nativePlugin('Share');if(fs&&share){const name='in-ordine-backup-'+new Date().toISOString().slice(0,10)+'.json';await fs.writeFile({path:name,data:btoa(unescape(encodeURIComponent(payload))),directory:'CACHE'});const uri=await fs.getUri({path:name,directory:'CACHE'});await share.share({title:'Backup In Ordine',url:uri.uri});return}const blob=new Blob([payload],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='in-ordine-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
const defaultCategories=['Stipendio','Pensione','Casa','Spesa','Auto','Salute','Tempo libero','Altro'];
function categorySettings(){const cats=state.preferences.categories||defaultCategories;shell('<header class="page-header money-head"><button data-go="settings">‹</button><div><small>IMPOSTAZIONI</small><h1>Categorie</h1></div><span class="eds">E.D.S.</span></header><div id="categoryList">'+cats.map((x,i)=>'<article class="card task"><b>'+escapeHtml(x)+'</b><button data-delete-category="'+i+'">Elimina</button></article>').join('')+'</div><form id="categoryForm" class="card form-card"><label>Nuova categoria<input id="categoryName" required autocomplete="off"></label><button type="submit">Aggiungi categoria</button></form>')}
function preferencesSettings(){const p=state.preferences;shell('<header class="page-header"><button data-go="settings">‹</button><div><small>IMPOSTAZIONI</small><h1>Preferenze</h1></div><span class="eds">E.D.S.</span></header><form id="preferencesForm" class="card form-card"><label>Formato data<select id="dateFormat"><option value="dd/mm/yyyy" '+(p.dateFormat==='dd/mm/yyyy'?'selected':'')+'>GG/MM/AAAA</option><option value="yyyy-mm-dd" '+(p.dateFormat==='yyyy-mm-dd'?'selected':'')+'>AAAA-MM-GG</option></select></label><label>Dimensione testo<select id="textSize"><option value="medium">Normale</option><option value="large" '+(p.textSize==='large'?'selected':'')+'>Grande</option></select></label><label class="check"><input id="reduceAnimations" type="checkbox" '+(p.reduceAnimations?'checked':'')+'> Riduci animazioni</label><button type="submit">Salva preferenze</button></form>')}
function financeNotificationSettings(){const n=state.financeNotifications||{};const list=state.entries.map(x=>`<label class="notification-entry"><input type="checkbox" data-notify-finance="${x.id}" ${x.reminder?.enabled||x.notify?'checked':''}><span><b>${escapeHtml(x.description)}</b><small>${fmtItalianDate(x.date)} · ${x.kind==='income'?'Entrata':'Pagamento'}</small></span><button type="button" data-edit-money-notice="${x.id}">Quando</button></label>`).join('');shell(`<header class="page-header money-head"><button data-go="money">‹</button><div><small>CONTI ECONOMICI</small><h1><svg class="bell-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Notifiche</h1></div><span class="eds">E.D.S.</span></header><form id="financeNotificationsForm" class="card form-card"><label class="check"><input id="financeNotificationsEnabled" type="checkbox" ${n.enabled?'checked':''}> Attiva tutte le notifiche</label><label>Ora predefinita<input id="financeDefaultTime" type="time" value="${escapeHtml(n.defaultTime||'09:00')}"></label><button type="submit">Salva impostazioni generali</button></form><section class="card notification-list"><h2>Notifiche per ogni voce</h2>${list||'<p>Nessuna voce inserita.</p>'}</section>`)}
