function profileSettings(){shell('<header class="page-header"><button data-go="settings">‹</button><div><small>IMPOSTAZIONI</small><h1>Profilo</h1></div><span class="eds">E.D.S.</span></header><form id="profileForm" class="card form-card"><label>Nome<input id="profileName" value="'+escapeHtml(state.profile?.fullName||'')+'" autocomplete="name"></label><label>Colore principale<select id="appColor"><option '+(state.appColor==='Blu'?'selected':'')+'>Blu</option><option '+(state.appColor==='Verde'?'selected':'')+'>Verde</option><option '+(state.appColor==='Viola'?'selected':'')+'>Viola</option></select></label><button type="submit">Salva</button></form>')}
