async function authenticateIfNeeded(){if(!state.preferences?.biometricEnabled)return true;if(!Capacitor.isNativePlatform())return false;const bio=nativePlugin('NativeBiometric');if(!bio)return false;try{const available=await bio.isAvailable();if(!available?.isAvailable)return false;await bio.verifyIdentity({reason:'Accedi a In Ordine',title:'In Ordine',subtitle:'Conferma la tua identità'});return true}catch{return false}}
function settings(){shell('<header class="page-header"><button data-go="landing">‹</button><div><small>IN ORDINE</small><h1>Impostazioni</h1></div><span class="eds">E.D.S.</span></header><div class="settings-list"><button class="wide card" data-go="finance-notifications"><svg class="bell-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Notifiche Conti economici</button><button class="wide card" data-go="summary">Riepilogo</button><button class="wide card" data-go="budget">Budget</button><button class="wide card" data-go="profile">Profilo / Nome</button><button class="wide card" data-go="categories">Categorie</button><button class="wide card" data-go="appearance">Colori e tema</button><button class="wide card" data-go="backup">Backup e ripristino</button><button class="wide card" data-go="preferences">Preferenze</button><button class="wide card" data-go="security">Sicurezza</button><button class="wide card" data-go="data-management">Gestione dati</button></div>')}
