function backupSettings(){shell('<header class="page-header"><button data-go="settings">‹</button><div><small>IMPOSTAZIONI</small><h1>Backup e ripristino</h1></div><span class="eds">E.D.S.</span></header><section class="card form-card"><p>Salva una copia dei dati oppure ripristina un backup JSON creato da In Ordine.</p><button type="button" id="exportBackup">Esporta backup</button><label class="import-label">Ripristina da file<input id="importBackup" type="file" accept="application/json,.json"></label></section>')}
function monthHistory(kind,ym=monthKey()){return financeCompletedEntries(state).filter(x=>x.kind===kind&&monthOf(x)===ym)}
function summary(){const ym=monthKey(),inc=monthHistory('income',ym).reduce((s,x)=>s+Number(x.amount||0),0),exp=monthHistory('expense',ym).reduce((s,x)=>s+Number(x.amount||0),0),prev=addMonths(ym,-1),prevInc=monthHistory('income',prev).reduce((s,x)=>s+Number(x.amount||0),0),prevExp=monthHistory('expense',prev).reduce((s,x)=>s+Number(x.amount||0),0);shell('<header class="page-header money-head"><button data-go="money">‹</button><div><small>CONTI ECONOMICI</small><h1>Riepilogo</h1></div><span class="eds">E.D.S.</span></header><section class="balance card"><small>Saldo reale</small><strong>'+euro(realBalance())+'</strong></section><div class="area-grid"><div class="area-card income"><b>Entrate ricevute</b><strong>'+euro(inc)+'</strong></div><div class="area-card expense"><b>Pagamenti effettuati</b><strong>'+euro(exp)+'</strong></div></div><section class="card summary-card"><div class="summary-difference"><b>Differenza movimenti</b><strong>'+euro(inc-exp)+'</strong></div><small>'+monthName(ym)+'</small></section><section class="card compare"><b>Confronto con '+monthName(prev)+'</b><p>Entrate: '+euro(inc)+' · mese precedente '+euro(prevInc)+' · variazione '+euro(inc-prevInc)+'</p><p>Pagamenti: '+euro(exp)+' · mese precedente '+euro(prevExp)+' · variazione '+euro(exp-prevExp)+'</p></section><button class="wide card" data-go="budget">Apri budget</button>')}
function todo(){const pending=state.todo.tasks.length,done=state.todo.done.length;shell('<header class="page-header todo-head"><button data-go="landing" aria-label="Torna alla home">‹</button><div><small>PIANIFICA CON CALMA</small><h1>Cose da fare</h1></div><img class="eds-logo" src="../assets/eds-green-approved.png" alt="E.D.S."></header><section class="todo-hero card"><div class="todo-art-frame"><img class="section-art todo-art" src="../assets/todo-couple-checklist.webp" alt="Una coppia organizza attività e promemoria con una lista, un orologio e una campanella"></div><p>Piccoli passi, grandi soddisfazioni.</p></section><h2 class="section-kicker todo-kicker">La tua giornata, con più leggerezza</h2><div class="area-grid todo-areas"><button class="area-card pending" data-go="todo-active"><span class="tile-icon" aria-hidden="true">◷</span><b>In scadenza</b><strong>'+pending+'</strong><small>Attività ancora da fare</small><span class="tile-arrow" aria-hidden="true">›</span></button><button class="area-card completed" data-go="todo-done"><span class="tile-icon" aria-hidden="true">✓</span><b>Cose già fatte</b><strong>'+done+'</strong><small>Ogni piccolo traguardo</small><span class="tile-arrow" aria-hidden="true">›</span></button></div><button class="wide card primary-action" data-go="todo-add"><span class="action-plus" aria-hidden="true">+</span><span>Aggiungi cosa da fare</span><b aria-hidden="true">›</b></button><button class="wide card settings-action" data-go="todo-notifications"><span class="link-icon">♧</span><span>Notifiche<small>Orari, anticipi e riepiloghi</small></span><b aria-hidden="true">›</b></button><button class="wide card settings-action" data-go="todo-settings"><span class="link-icon">⚙</span><span>Impostazioni<small>Colori e notifiche</small></span><b aria-hidden="true">›</b></button>')}
function expandRecurring(entry){if(!entry.recurrenceRule||!entry.date)return;addOccurrences(state.entries,entry,entry.recurrenceRule,entry.datePrecision||'day')}
let todoFilters={active:{month:'all',year:'all'},done:{month:'all',year:'all'}};let todoListDone=false;
function todoFilterControls(items,done){const todoFilter=done?todoFilters.done:todoFilters.active;const years=[...new Set(items.map(x=>(x.date||'').slice(0,4)).filter(Boolean))].sort();return '<div class="todo-filters"><select id="todoMonth"><option value="all">Tutti i mesi</option>'+Array.from({length:12},(_,i)=>'<option value="'+String(i+1).padStart(2,'0')+'" '+(todoFilter.month===String(i+1).padStart(2,'0')?'selected':'')+'>'+new Intl.DateTimeFormat('it-IT',{month:'long'}).format(new Date(2026,i,1))+'</option>').join('')+'</select><select id="todoYear"><option value="all">Tutti gli anni</option>'+years.map(y=>'<option '+(todoFilter.year===y?'selected':'')+'>'+y+'</option>').join('')+'</select></div>'}
function filteredTodos(items,done){const todoFilter=done?todoFilters.done:todoFilters.active;return [...items].filter(x=>{const [y,m]=(x.date||'').split('-');return (todoFilter.month==='all'||m===todoFilter.month)&&(todoFilter.year==='all'||y===todoFilter.year)}).sort((a,b)=>{if(!a.date)return 1;if(!b.date)return -1;return a.date.localeCompare(b.date)})}
function shiftDateSafe(date,rule,i){const [y,m,d]=date.split('-').map(Number);if(rule==='monthly'){const target=new Date(y,m-1+i,1,12);const last=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();target.setDate(Math.min(d,last));return target.toISOString().slice(0,10)}if(rule==='yearly'){const targetYear=y+i,last=new Date(targetYear,m,0).getDate();return targetYear+'-'+String(m).padStart(2,'0')+'-'+String(Math.min(d,last)).padStart(2,'0')}return date}
function recurrenceDates(date,rule,count=24){if(!date||rule==='none')return[];const out=[];for(let i=1;i<=count;i++)out.push(shiftDateSafe(date,rule,i));return out}
function moneyTotals(kind,ym){return financeTotals(state,kind,ym)}
function todoAdd(){shell(`<header class="page-header todo-head"><button data-go="todo">‹</button><div><small>COSE DA FARE</small><h1>Nuova attività</h1></div><span class="eds">E.D.S.</span></header><form id="todoForm" class="card form-card"><label>Cosa devi fare?<input id="todoDescription" required autocomplete="off"></label>${dateControls('todo',{datePrecision:'day'})}${recurrenceFields('todo')}${reminderControls('todo',{},'todo')}<button type="submit">Salva attività</button></form>`);syncDateMode('todo');syncRecurrenceMode('todo');syncReminderMode('todo')}
function todoEdit(id,done=false){const list=done?state.todo.done:state.todo.tasks,x=list.find(t=>t.id===id);if(!x)return todoList(done);const recurring=Boolean(x.seriesId||x.recurrenceRule||x.recurrenceSource);shell(`<header class="page-header todo-head"><button data-go="${done?'todo-done':'todo-active'}">‹</button><div><small>COSE DA FARE</small><h1>Modifica attività</h1></div><span class="eds">E.D.S.</span></header><form id="todoEditForm" data-id="${x.id}" data-done="${done}" data-series="${recurring}" class="card form-card"><label>Descrizione<input id="todoEditDescription" value="${escapeHtml(x.description)}" required></label>${dateControls('todoEdit',x)}${recurrenceFields('todoEdit',x)}${reminderControls('todoEdit',x,'todo')}<button type="submit">Salva modifiche</button><button type="button" class="danger" data-delete-task="${x.id}" data-done="${done}">Elimina attività</button></form>`);syncDateMode('todoEdit');syncRecurrenceMode('todoEdit');syncReminderMode('todoEdit')}
function todoList(done=false){todoListDone=done;const source=done?state.todo.done:state.todo.tasks,items=filteredTodos(source,done).filter(x=>matchesSearch(x,todoSearch[done?'done':'active']));const rows=items.length?items.map(x=>'<article class="card task" data-edit-task="'+x.id+'" data-done="'+done+'"><div><b>'+escapeHtml(x.description)+'</b><small>'+(done?'Completata il '+fmtItalianDate((x.completedAt||'').slice(0,10)):fmtItalianDate(x.date))+'</small></div>'+(done?'<button data-restore="'+x.id+'">Ripristina</button>':'<button data-complete="'+x.id+'" class="todo-complete"><span aria-hidden="true">○</span> Segna come fatta</button>')+'</article>').join(''):'<div class="card empty"><b>Nessuna attività</b><p>'+(done?'Le attività completate compariranno qui.':'Aggiungi la prima cosa da fare.')+'</p></div>';shell('<header class="page-header todo-head"><button data-go="todo">‹</button><div><small>COSE DA FARE</small><h1>'+(done?'Cose già fatte':'In scadenza')+'</h1></div><span class="eds">E.D.S.</span></header>'+todoFilterControls(source,done)+'<label class="search-field">Cerca attività<input data-todo-search="'+(done?'done':'active')+'" type="search" placeholder="Cerca nelle attività" value="'+escapeHtml(todoSearch[done?'done':'active'])+'"></label>'+rows+(done?'':'<button class="wide card add-action todo-add-action" data-go="todo-add"><span class="action-plus" aria-hidden="true">+</span><span>Aggiungi attività</span><b aria-hidden="true">›</b></button>'))}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function placeholder(title,back){shell('<header class="page-header"><button data-go="'+back+'">‹</button><div><small>IN ORDINE</small><h1>'+title+'</h1></div><span class="eds">E.D.S.</span></header><div class="card empty"><b>'+title+'</b><p>La funzione viene ricostruita nella V2 mantenendo le regole dell’app originale.</p></div>')}
function route(name){if(name==='landing')landing();else if(name==='money')money();else if(name==='todo')todo();else if(name==='income'||name==='expense')flow(name);else if(name==='movements')movements();else if(name==='summary')summary();else if(name==='budget')budget();else if(name==='budget-categories')budgetCategory();else if(name==='categories')categorySettings();else if(name==='profile')profileSettings();else if(name==='data-management')resetSettings();else if(name==='preferences')preferencesSettings();else if(name==='security')securitySettings();else if(name==='settings')settings();else if(name==='appearance')appearanceSettings();else if(name==='backup')backupSettings();else if(name==='todo-settings')todoSettings();else if(name==='todo-notifications')todoSettings();else if(name==='todo-settings-color')todoColorSettings();else if(name==='finance-notifications')financeNotificationSettings();else if(name==='todo-add')todoAdd();else if(name==='todo-active')todoList(false);else if(name==='todo-done')todoList(true);else placeholder(({income:'Entrate',expense:'Pagamenti',movements:'Movimenti',summary:'Riepilogo e budget','todo-active':'In scadenza','todo-done':'Cose già fatte','todo-add':'Nuova attività','todo-settings':'Impostazioni'})[name]||'In Ordine',name.startsWith('todo-')?'todo':'money')}
