app.addEventListener('input',e=>{const el=e.target;let selector='',render=null;if(el.id==='movementSearch'){movementSearch=el.value;selector='#movementSearch';render=()=>movements()}else if(el.dataset.moneySearch){const k=el.dataset.moneySearch;moneySearch[k]=el.value;selector='[data-money-search="'+k+'"]';render=()=>flow(k)}else if(el.dataset.todoSearch){const k=el.dataset.todoSearch;todoSearch[k]=el.value;selector='[data-todo-search="'+k+'"]';render=()=>todoList(k==='done')}if(render){const pos=el.selectionStart;render();const next=document.querySelector(selector);next?.focus();next?.setSelectionRange(pos,pos)}});
